// Bech32 checksum primitives (BIP-173 reference algorithm).

const GENERATORS = [0x3b6a57b2, 0x26508e6d, 0x1ea119fa, 0x3d4233dd, 0x2a1462b3];

// Internal checksum constant for the original bech32 encoding.
export const BECH32_CONST = 1;

// Compute the Bech32 polynomial modulus over an array of 5-bit values.
export function bech32Polymod(values) {
  let chk = 1;
  for (const v of values) {
    const top = chk >> 25;
    chk = ((chk & 0x1ffffff) << 5) ^ v;
    for (let i = 0; i < 5; i++) {
      if ((top >> i) & 1) {
        chk ^= GENERATORS[i];
      }
    }
  }
  return chk >>> 0;
}

// Expand the HRP into high and low 5-bit groups separated by a zero.
export function bech32HrpExpand(hrp) {
  const expanded = [];
  for (const ch of hrp) {
    expanded.push(ch.codePointAt(0) >> 5);
  }
  expanded.push(0);
  for (const ch of hrp) {
    expanded.push(ch.codePointAt(0) & 31);
  }
  return expanded;
}

// Verify the checksum embedded in the last 6 data values.
export function bech32VerifyChecksum(hrp, data) {
  return bech32Polymod(bech32HrpExpand(hrp).concat(data)) === BECH32_CONST;
}

// Bech32 string decoder, mirroring the behavior of the Python
// reference implementation's bech32_decode function:
//   - returns { hrp, data } on success
//   - returns { hrp: null, data: null } on any decoding failure

import { CHARSET } from './charset.mjs';
import { bech32VerifyChecksum } from './checksum.mjs';

const MAX_LENGTH = 90;

export function bech32Decode(bech) {
  // Reject characters outside the printable ASCII range [33, 126]
  // and strings mixing upper and lower case.
  let outOfRange = false;
  for (const ch of bech) {
    const code = ch.codePointAt(0);
    if (code < 33 || code > 126) {
      outOfRange = true;
      break;
    }
  }
  if (outOfRange || (bech.toLowerCase() !== bech && bech.toUpperCase() !== bech)) {
    return { hrp: null, data: null };
  }

  const lowered = bech.toLowerCase();
  const pos = lowered.lastIndexOf('1');
  if (pos < 1 || pos + 7 > lowered.length || lowered.length > MAX_LENGTH) {
    return { hrp: null, data: null };
  }

  const dataPart = lowered.slice(pos + 1);
  for (const ch of dataPart) {
    if (!CHARSET.includes(ch)) {
      return { hrp: null, data: null };
    }
  }

  const hrp = lowered.slice(0, pos);
  const data = [...dataPart].map((ch) => CHARSET.indexOf(ch));

  if (!bech32VerifyChecksum(hrp, data)) {
    return { hrp: null, data: null };
  }

  return { hrp, data: data.slice(0, data.length - 6) };
}

// Helpers to render values exactly like Python's repr()/print() would,
// so console.log output matches the original script character by character.

// Python str repr: single quotes by default; double quotes when the string
// contains a single quote but no double quote; backslash-escapes otherwise.
export function pyReprString(s) {
  const hasSingle = s.includes("'");
  const hasDouble = s.includes('"');
  const quote = hasSingle && !hasDouble ? '"' : "'";
  let body = '';
  for (const ch of s) {
    const code = ch.codePointAt(0);
    if (ch === '\\') {
      body += '\\\\';
    } else if (ch === quote) {
      body += '\\' + quote;
    } else if (ch === '\n') {
      body += '\\n';
    } else if (ch === '\r') {
      body += '\\r';
    } else if (ch === '\t') {
      body += '\\t';
    } else if (code < 32 || code === 127) {
      body += '\\x' + code.toString(16).padStart(2, '0');
    } else {
      body += ch;
    }
  }
  return quote + body + quote;
}

// Python list-of-ints repr: "[0, 1, 2]" / "[]".
export function pyReprIntList(values) {
  return '[' + values.join(', ') + ']';
}

// Render the decode result like Python's print() of the
// (hrp, data) tuple: "(None, None)" or "('hrp', [0, 1])".
export function formatDecodeResult({ hrp, data }) {
  if (hrp === null || data === null) {
    return '(None, None)';
  }
  return '(' + pyReprString(hrp) + ', ' + pyReprIntList(data) + ')';
}

// Minimal re-implementation of the Python argparse behavior used by the
// original script: a single required string option --a, plus -h/--help.
// Error messages, exit codes, and stream selection mirror argparse.

import { basename } from 'node:path';

const NEGATIVE_NUMBER = /^-\d+$|^-\d*\.\d+$/;

export function getProgName() {
  return basename(process.argv[1] || 'test2.mjs');
}

function usageLine(prog) {
  return `usage: ${prog} [-h] --a A`;
}

function printHelp(prog) {
  process.stdout.write(
    usageLine(prog) +
      '\n\n' +
      'options:\n' +
      '  -h, --help  show this help message and exit\n' +
      '  --a A\n'
  );
}

function fail(prog, message) {
  process.stderr.write(usageLine(prog) + '\n' + `${prog}: error: ${message}` + '\n');
  process.exit(2);
}

// A token "looks like an option string" (and thus cannot be swallowed as
// a value) when it starts with '-', is longer than one char, and is not a
// negative number (no option strings here look like negative numbers).
function looksLikeOption(token) {
  return token.length > 1 && token.startsWith('-') && !NEGATIVE_NUMBER.test(token);
}

// Resolve a long-option token (without leading dashes) to its canonical
// name, honoring argparse's unique-prefix abbreviation.
// Returns { name } on match, { ambiguous: [...] } or null.
function resolveLong(name) {
  const options = ['help', 'a'];
  if (options.includes(name)) {
    return { name };
  }
  const matches = options.filter((opt) => opt.startsWith(name));
  if (matches.length === 1) {
    return { name: matches[0] };
  }
  if (matches.length > 1) {
    return { ambiguous: matches };
  }
  return null;
}

// Parse process.argv-style arguments (already stripped of node + script).
// Returns { a } on success; prints help/errors and exits otherwise.
export function parseArgs(argv) {
  const prog = getProgName();
  const args = { a: undefined };
  const extras = [];
  let positionalOnly = false;

  for (let i = 0; i < argv.length; i++) {
    const token = argv[i];

    if (positionalOnly) {
      extras.push(token);
      continue;
    }
    if (token === '--') {
      positionalOnly = true;
      continue;
    }

    if (token.startsWith('--')) {
      const eq = token.indexOf('=');
      const rawName = eq === -1 ? token.slice(2) : token.slice(2, eq);
      const inlineValue = eq === -1 ? undefined : token.slice(eq + 1);
      const resolved = resolveLong(rawName);

      if (resolved === null) {
        extras.push(token);
        continue;
      }
      if (resolved.ambiguous) {
        fail(prog, `ambiguous option: --${rawName} could match ${resolved.ambiguous.map((o) => '--' + o).join(', ')}`);
      }

      if (resolved.name === 'help') {
        printHelp(prog);
        process.exit(0);
      }

      // resolved.name === 'a'
      if (inlineValue !== undefined) {
        args.a = inlineValue;
      } else {
        const next = argv[i + 1];
        if (next === undefined || looksLikeOption(next)) {
          fail(prog, 'argument --a: expected one argument');
        }
        args.a = next;
        i++;
      }
      continue;
    }

    if (token.startsWith('-') && token.length > 1 && !NEGATIVE_NUMBER.test(token)) {
      if (token === '-h') {
        printHelp(prog);
        process.exit(0);
      }
      extras.push(token);
      continue;
    }

    // Bare positional token: this parser declares no positionals.
    extras.push(token);
  }

  if (args.a === undefined) {
    fail(prog, 'the following arguments are required: --a');
  }
  if (extras.length > 0) {
    fail(prog, `unrecognized arguments: ${extras.join(' ')}`);
  }

  return args;
}

// Entry point — Node.js (ESM) port of test2.py.
// Decodes a Bech32 string given via --a and prints the (hrp, data) tuple
// in Python's repr format.

import { parseArgs } from './lib/argparse.mjs';
import { bech32Decode } from './lib/decoder.mjs';
import { formatDecodeResult } from './lib/pyformat.mjs';

function main() {
  const args = parseArgs(process.argv.slice(2));
  const result = bech32Decode(args.a);
  console.log(formatDecodeResult(result));
}

main();

